extension BrandLogos {
  private static func squash(_ s: String) -> String {
    s.lowercased().replacingOccurrences(of: "+", with: "plus").replacingOccurrences(of: ".", with: "dot").filter { $0.isASCII && ($0.isLetter || $0.isNumber) }
  }

  /** The bundled logo for an app, by any of its names (its connector id, its name, its brand), as the web's brandLogo. */
  static func find(_ names: String?...) -> BundledLogo? { find(names) }
  static func find(_ names: [String?]) -> BundledLogo? {
    for raw in names {
      guard let raw else { continue }
      let lower = raw.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
      let key = aliases[lower] ?? (all[squash(lower)] != nil ? squash(lower) : aliases[squash(lower)])
      if let key, let logo = all[key] { return logo }
    }
    return nil
  }

  /** Near-black marks (GitHub, Notion, X…) are drawn in the text colour, so they turn light in dark mode. */
  static func isDark(_ hex: String) -> Bool {
    guard let n = UInt32(hex, radix: 16) else { return false }
    return 0.2126 * Double((n >> 16) & 255) + 0.7152 * Double((n >> 8) & 255) + 0.0722 * Double(n & 255) < 60
  }
}

/** A bundled logo on its tile (the web's BrandTile): white in light mode, dark grey in dark mode, the mark at 56%. */
struct BundledLogoTile: View {
  var logo: BundledLogo
  var size: CGFloat = 42
  var body: some View {
    SVGShape(box: CGRect(x: 0, y: 0, width: 24, height: 24), commands: logo.path)
      .fill(BrandLogos.isDark(logo.hex) ? Palette.text : ChatWall.color("#" + logo.hex))
      .frame(width: size * 0.56, height: size * 0.56)
      .frame(width: size, height: size)
      .background(Color(light: 0xFFFFFF, dark: 0x2C2C2E), in: RoundedRectangle(cornerRadius: size * 0.27, style: .continuous))
      .overlay(RoundedRectangle(cornerRadius: size * 0.27, style: .continuous).strokeBorder(Color(light: 0x000000, lightAlpha: 0.1, dark: 0xFFFFFF, darkAlpha: 0.1)))
      .accessibilityHidden(true)
  }
}

/** An app's tile: the logo Bubble AI carries, else the one the hub finds (or the registry's own), else a plain line icon. */
struct AppTile: View {
  var name: String
  var ids: [String?] = []
  var sources: [String]? = nil
  var symbol = "powerplug"
  var size: CGFloat = 42
  var body: some View {
    if let logo = BrandLogos.find([name] + ids) {
      BundledLogoTile(logo: logo, size: size)
    } else {
      AppLogo(sources: sources ?? AppLogo.byName(name), symbol: symbol, size: size)
    }
  }
}
